using CertDesk.Common; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Forms;
public partial class MchdEditForm:Form { public Mchd Mchd{get;} ComboBox pr=new(){Width=320,DropDownStyle=ComboBoxStyle.DropDownList}, rep=new(){Width=320,DropDownStyle=ComboBoxStyle.DropDownList}, cert=new(){Width=320,DropDownStyle=ComboBoxStyle.DropDownList}; TextBox num=new(){Width=320}, powers=new(){Width=320,Height=70,Multiline=true}, codes=new(){Width=320}, notes=new(){Width=320}; DateTimePicker vf=new(),vt=new(); CheckBox reg=new(){Text="Зарегистрирована"}; public MchdEditForm(Mchd? m=null){Mchd=m??new Mchd(); InitializeComponent(); Build(); Lists(); if(m!=null) LoadM();} void Build(){int y=15; void row(string l,Control c){Controls.Add(new Label{Text=l,Left=20,Top=y+3,Width=155}); c.Left=190;c.Top=y;Controls.Add(c);y+=c.Height+12;} row("Номер МЧД",num); row("Доверитель",pr); row("Представитель",rep); row("Сертификат",cert); row("Полномочия",powers); row("Коды полномочий",codes); row("Действует с",vf); row("Действует до",vt); row("Примечание",notes); reg.Left=190;reg.Top=y;Controls.Add(reg); var ok=new Button{Text="Сохранить",Left=190,Top=y+40}; var cancel=new Button{Text="Отмена",Left=310,Top=y+40,DialogResult=DialogResult.Cancel};UiTheme.ApplyButtonStyle(ok);Controls.AddRange(new Control[]{ok,cancel});ok.Click+=Save;} void Lists(){ pr.Items.Add(new ComboBoxItem{Text="Не указан"}); cert.Items.Add(new ComboBoxItem{Text="Не указан"}); foreach(var e in EmployeeService.GetActive()){pr.Items.Add(new ComboBoxItem{Id=e.Id,Text=e.FullName});rep.Items.Add(new ComboBoxItem{Id=e.Id,Text=e.FullName});} foreach(var c in CertificateService.GetAll()) cert.Items.Add(new ComboBoxItem{Id=c.Id,Text=c.SerialNumber}); pr.SelectedIndex=0; if(rep.Items.Count>0)rep.SelectedIndex=0; cert.SelectedIndex=0;} void LoadM(){num.Text=Mchd.Number;Sel(pr,Mchd.PrincipalEmployeeId);Sel(rep,Mchd.RepresentativeEmployeeId);Sel(cert,Mchd.CertificateId);powers.Text=Mchd.Powers;codes.Text=Mchd.PowersCodes;vf.Value=Mchd.ValidFrom;vt.Value=Mchd.ValidTo;reg.Checked=Mchd.IsRegistered;notes.Text=Mchd.Notes;} void Sel(ComboBox c,int? id){foreach(ComboBoxItem i in c.Items)if(i.Id==id){c.SelectedItem=i;break;}} void Save(object? _,EventArgs __){ if(string.IsNullOrWhiteSpace(num.Text)||rep.SelectedItem==null||string.IsNullOrWhiteSpace(powers.Text)){MessageHelper.Error("Заполните номер, представителя и полномочия");return;} if(vt.Value.Date<vf.Value.Date){MessageHelper.Error("Дата окончания не может быть раньше начала");return;} Mchd.Number=num.Text.Trim();Mchd.PrincipalEmployeeId=((ComboBoxItem)pr.SelectedItem).Id;Mchd.RepresentativeEmployeeId=((ComboBoxItem)rep.SelectedItem).Id!.Value;Mchd.CertificateId=((ComboBoxItem)cert.SelectedItem).Id;Mchd.Powers=powers.Text;Mchd.PowersCodes=codes.Text;Mchd.ValidFrom=vf.Value;Mchd.ValidTo=vt.Value;Mchd.IsRegistered=reg.Checked;Mchd.Notes=notes.Text;DialogResult=DialogResult.OK;} }
